import numpy as np
from multiprocessing import Pool, cpu_count
from scipy.optimize import minimize
import sys
sys.path.append('storage/praxis')
from lp_utils import solve_radii_lp

def get_seed(seed_val):
    """Robust seeding function from the Adaptive Search method."""
    rng = np.random.default_rng(seed_val)
    seed_type = seed_val % 3
    if seed_type == 0:
        grid = np.stack(np.meshgrid(np.linspace(0.1,0.9,6), np.linspace(0.1,0.9,6)),-1).reshape(-1,2)[:32]
        return np.clip(grid + (rng.random((32,2))-0.5)*0.08, 0.05, 0.95)
    elif seed_type == 1:
        points = [rng.uniform(0.1, 0.9, 2)]; [points.append(candidates[np.argmax(np.min(np.sum((candidates[:,np.newaxis,:] - np.array(points)[np.newaxis,:,:])**2, axis=-1), axis=1))]) for _ in range(31) for candidates in [rng.uniform(0.1,0.9,(200,2))]]; return np.array(points)
    else:
        rows=[5,6,5,6,5,5]; points=[]; y=0.95
        for i,c in enumerate(rows): x_s=(1.0-(c-1)*0.15)/2; [points.append([x_s+j*0.15,y]) for j in range(c)]; y-=0.15
        return np.array(points)[:32]

def refine_slsqp(centers):
    """Standard deep SLSQP refinement."""
    x0 = np.hstack([centers, np.full((32,1),0.05)]).flatten()
    def obj(x): return -np.sum(x[2::3])
    def cons(x):
        c,r=x.reshape(32,3)[:,:2],x[2::3]
        I,J=np.triu_indices(32,1); d2=np.sum((c[I]-c[J])**2,1); r2=(r[I]+r[J])**2
        return np.concatenate([c[:,0]-r,1-c[:,0]-r,c[:,1]-r,1-c[:,1]-r,d2-r2])
    res=minimize(obj,x0,method='SLSQP',bounds=[(0,1)if j%3<2 else(1e-12,None)for j in range(32*3)],constraints={'type':'ineq','fun':cons},options={'maxiter':1000,'ftol':1e-12})
    if not res.success: return centers, np.zeros(32), 0.0
    final_x = res.x
    return final_x.reshape(32,3)[:,:2], final_x[2::3], -res.fun

def refine_micro_jitter(centers):
    """Verity-style stochastic refinement."""
    rng = np.random.default_rng()
    steps = 1000; sigma = 0.005
    centers_best = centers.copy()
    radii_best = solve_radii_lp(centers_best)
    score_best = np.sum(radii_best)
    if score_best < 1e-6: return centers, radii_best, score_best
    for _ in range(steps):
        centers_try = centers_best.copy()
        i = int(rng.integers(0, 32))
        delta = rng.normal(0.0, sigma, size=2)
        centers_try[i] = np.clip(centers_try[i] + delta, 1e-6, 1.0 - 1e-6)
        radii_try = solve_radii_lp(centers_try)
        score_try = np.sum(radii_try)
        if score_try > score_best:
            centers_best, radii_best, score_best = centers_try, radii_try, score_try
    return centers_best, radii_best, score_best

def hybrid_worker(seed_val):
    """Assigns a refinement method based on the seed."""
    initial_centers = get_seed(seed_val)
    if seed_val % 2 == 0:
        return refine_slsqp(initial_centers)
    else:
        return refine_micro_jitter(initial_centers)

def construct_packing() -> tuple:
    NUM_CANDIDATES = 128
    with Pool(processes=cpu_count()) as pool:
        results = pool.map(hybrid_worker, range(NUM_CANDIDATES))

    best_centers, best_radii, best_score = None, None, -1.0
    for centers, radii, score in results:
        if score > best_score:
            best_centers, best_radii, best_score = centers, radii, score

    if best_centers is None: return get_seed(0), np.full((32,), 0.05)
    return best_centers, best_radii * (1.0 - 1e-12)
